## 4. Concrete Data Structures & API Specifications

### 4.1 Invariant-Safe Event Bus Architecture

To prevent silent contract drift across async subsystems without static TS checks, the event bus implements a runtime schema enforcement layer:

```javascript
// src/core/event-bus-guard.js
import { EventEmitter } from 'events';
import { z } from 'zod';
import { logger } from '../utils/logger.js';

// Canonical Invariant Schemas
export const EventSchemas = {
  'riley.insights.generated': z.object({
    organizationId: z.string().uuid(),
    analysisType: z.enum(['overview', 'churn_risk', 'upsell', 'anomaly']),
    insights: z.array(z.object({
      id: z.string(),
      type: z.string(),
      confidence: z.number().min(0).max(1),
      data: z.record(z.unknown()),
      recommendedAction: z.string().optional()
    })),
    timestamp: z.number().int()
  }),
  'customer.high_value_action': z.object({
    organizationId: z.string().uuid(),
    customerId: z.string(),
    actionType: z.string(),
    monetaryValue: z.number().nonnegative(),
    metadata: z.record(z.unknown())
  })
};

export class GuardedEventBus extends EventEmitter {
  emit(eventName, payload) {
    const schema = EventSchemas[eventName];
    if (schema) {
      const validation = schema.safeParse(payload);
      if (!validation.success) {
        logger.error(`[EventBus Invariant Violation] Invalid payload for event '${eventName}'`, {
          errors: validation.error.format(),
          payload
        });
        throw new TypeError(`Event contract violated for: ${eventName}`);
      }
    }
    return super.emit(eventName, { payload, emittedAt: Date.now() });
  }
}
```

### 4.2 Resilient Identity Resolution Algorithm

The identity resolution engine must guarantee that probabilistic confidence never degenerates under partial or malformed signals:

$$\text{Confidence}_{\text{composite}} = 1 - \prod_{i=1}^{k} \left(1 - w_i \cdot s_i\right)$$

Where $w_i \in [0.1, 1.0]$ represents signal weight and $s_i \in [0, 1]$ represents signal quality.

```javascript
// src/core/identity-resolution/invariant-resolver.js
import { prisma } from '../prisma.js';
import { logger } from '../../utils/logger.js';

export const SignalWeights = Object.freeze({
  email: 1.0,
  phone: 0.9,
  user_id: 0.9,
  device_id: 0.6,
  cookie_id: 0.5,
  ip_address: 0.3,
});

export class SafeIdentityResolver {
  static MIN_CONFIDENCE = 0.70;

  static sanitizeSignals(signals) {
    if (!Array.isArray(signals)) return [];
    return signals.filter(sig => 
      sig &&
      typeof sig.type === 'string' &&
      typeof sig.value === 'string' &&
      sig.value.trim().length > 0 &&
      SignalWeights[sig.type] !== undefined
    ).map(sig => ({
      type: sig.type.toLowerCase(),
      value: sig.value.trim().toLowerCase(),
      weight: SignalWeights[sig.type.toLowerCase()]
    }));
  }

  async resolve(rawSignals, organizationId) {
    if (!organizationId || typeof organizationId !== 'string') {
      throw new Error('Invariant Violation: organizationId is required for identity resolution');
    }

    const signals = SafeIdentityResolver.sanitizeSignals(rawSignals);
    if (signals.length === 0) return null;

    // 1. Deterministic Strategy
    const deterministic = await this.deterministicMatch(signals, organizationId);
    if (deterministic) return deterministic;

    // 2. Probabilistic Strategy with strict mathematical clipping
    return this.probabilisticMatch(signals, organizationId);
  }

  async deterministicMatch(signals, organizationId) {
    const primarySignal = signals.find(s => s.type === 'email' || s.type === 'user_id');
    if (!primarySignal) return null;

    const match = await prisma.customer.findFirst({
      where: {
        organizationId,
        OR: [
          { email: primarySignal.type === 'email' ? primarySignal.value : undefined },
          { externalId: primarySignal.type === 'user_id' ? primarySignal.value : undefined }
        ]
      }
    });

    if (match) {
      return {
        customerId: match.id,
        confidence: 1.0,
        strategy: 'DETERMINISTIC',
        matchedSignal: primarySignal
      };
    }
    return null;
  }

  async probabilisticMatch(signals, organizationId) {
    let unmergedProbability = 1.0;
    const matchedTypes = [];

    for (const signal of signals) {
      unmergedProbability *= (1.0 - signal.weight);
      matchedTypes.push(signal.type);
    }

    const compositeScore = Math.min(1.0, Math.max(0.0, 1.0 - unmergedProbability));

    if (compositeScore >= SafeIdentityResolver.MIN_CONFIDENCE) {
      return {
        confidence: Number(compositeScore.toFixed(4)),
        strategy: 'PROBABILISTIC',
        matchedSignals: matchedTypes
      };
    }
    return null;
  }
}
```

