## 3. Concrete Technical Specifications

### 3.1 Data Structures & Serialization Contracts

#### 3.1.1 Request Query Parameters (AIP-158 / AIP-132 Compliant)
```typescript
interface ListUsersRequestQuery {
  // Pagination
  pageSize?: number;       // Default: 20, Max: 100 (formerly `limit`)
  pageToken?: string;      // Base64Url-encoded opaque cursor (replaces integer `page`)

  // Predicate Filtering
  status?: 'active' | 'suspended' | 'pending_verification' | 'deleted';
  role?: 'admin' | 'developer' | 'viewer' | 'service_account';
  provider?: 'local' | 'google' | 'github' | 'saml';

  // Search & Sorting
  query?: string;          // Substring / prefix search on email or name
  orderBy?: string;        // E.g., "createdAt:desc" | "lastLoginAt:desc" | "email:asc"
}
```

#### 3.1.2 Response Envelope Structure
```typescript
interface ListUsersResponseEnvelope<T = UserDTO> {
  data: T[];
  pagination: {
    nextPageToken: string | null;
    prevPageToken: string | null;
    totalCount?: number;   // Optional/Estimated to avoid expensive COUNT(*) queries
    hasMore: boolean;
  };
  meta: {
    requestId: string;
    servedFromCache: boolean;
    timestamp: string;
  };
}

interface UserDTO {
  id: string;
  email: string;
  name: string;
  role: string;
  status: string;
  provider: string;
