### 5.1 Deterministic Cache Key Generation
```typescript
function buildListCacheKey(filters: Record<string, any>, pagination: Record<string, any>): string {
  const normalized = {
    s: filters.status || '*',
    r: filters.role || '*',
    p: filters.provider || '*',
    ps: pagination.pageSize || 20,
    pt: pagination.pageToken || 'START'
