### 3.2 Concrete Algorithms & Implementation

#### 3.2.1 Opaque Keyset Cursor Encoding/Decoding Algorithm
Offset pagination (`OFFSET = (page - 1) * limit`) incurs $O(N)$ scan overhead at deep pages and suffers from "page drift" during concurrent insertions. Keyset pagination guarantees $O(1)$ index seek performance.

```typescript
// services/user-service/src/utils/cursorPagination.js

import { Buffer } from 'node:buffer';
import crypto from 'node:crypto';

const CURSOR_SECRET = process.env.CURSOR_SECRET || 'ailab-default-cursor-secret-key';

export interface CursorPayload {
  createdAt: string;
  id: string;
}

export function encodeCursor(payload: CursorPayload): string {
  const jsonStr = JSON.stringify([payload.createdAt, payload.id]);
  const hmac = crypto.createHmac('sha256', CURSOR_SECRET).update(jsonStr).digest('hex').slice(0, 16);
  return Buffer.from(`${jsonStr}__sig_${hmac}`).toString('base64url');
}

export function decodeCursor(token: string): CursorPayload | null {
  try {
    const raw = Buffer.from(token, 'base64url').toString('utf8');
    const [jsonStr, sig] = raw.split('__sig_');

    if (!jsonStr || !sig) return null;

    const expectedSig = crypto.createHmac('sha256', CURSOR_SECRET).update(jsonStr).digest('hex').slice(0, 16);
    if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) {
      return null;
    }

    const [createdAt, id] = JSON.parse(jsonStr);
    return { createdAt, id };
  } catch {
    return null;
  }
}
```

#### 3.2.2 Hardened Service Layer Implementation
```javascript
// services/user-service/src/services/userService.js

import { Op } from 'sequelize';
import { encodeCursor, decodeCursor } from '../utils/cursorPagination.js';
import logger from '../utils/logger.js';
import redisClient from '../utils/redis.js';

export class UserService {
  /**
   * List users with keyset pagination and predicate filtering.
   */
  async listUsers(filters = {}, options = {}) {
    try {
      const pageSize = Math.min(Math.max(Number.parseInt(options.pageSize, 10) || 20, 1), 100);
      const cursorPayload = options.pageToken ? decodeCursor(options.pageToken) : null;

      const where = {};

      // Predicate filtering
      if (filters.status) where.status = filters.status;
      if (filters.role) where.role = filters.role;
      if (filters.provider) where.provider = filters.provider;

      // Keyset cursor seek: (createdAt, id) < (cursor.createdAt, cursor.id)
      if (cursorPayload) {
        where[Op.or] = [
          {
            createdAt: {
              [Op.lt]: new Date(cursorPayload.createdAt)
            }
          },
          {
            createdAt: new Date(cursorPayload.createdAt),
            id: {
              [Op.lt]: cursorPayload.id
            }
          }
        ];
      }

      // Fetch pageSize + 1 to determine if hasMore is true
      const users = await User.findAll({
        where,
        limit: pageSize + 1,
        order: [
          ['createdAt', 'DESC'],
          ['id', 'DESC']
        ],
        attributes: { exclude: ['passwordHash', 'salt'] }
      });

      const hasMore = users.length > pageSize;
      const results = hasMore ? users.slice(0, pageSize) : users;

      let nextPageToken = null;
      if (hasMore && results.length > 0) {
        const lastItem = results[results.length - 1];
        nextPageToken = encodeCursor({
          createdAt: lastItem.createdAt.toISOString(),
          id: lastItem.id
        });
      }

      return {
        users: results,
        pagination: {
          nextPageToken,
          hasMore,
          pageSize
        }
      };
    } catch (error) {
      logger.error('Error executing listUsers:', { error: error.message, stack: error.stack });
      throw error;
    }
  }
}
```

