```typescript
// src/lib/content-store.ts
import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';

export interface PostEntity {
  slug: string;
  title: string;
  description: string;
  publishedAt: string;
  readingTime?: string;
  tags: string[];
  featured: boolean;
  content: string;
  contentHash: string;
}

class ContentRegistry {
  private static instance: ContentRegistry;
  private postMap: Map<string, PostEntity> = new Map();
  private sortedPosts: PostEntity[] = [];
  private isInitialized = false;

  private constructor() {}

  public static getInstance(): ContentRegistry {
    if (!ContentRegistry.instance) {
      ContentRegistry.instance = new ContentRegistry();
    }
    return ContentRegistry.instance;
  }

  public initialize(contentDir = path.join(process.cwd(), 'content', 'posts')): void {
    if (this.isInitialized && process.env.NODE_ENV === 'production') return;

    if (!fs.existsSync(contentDir)) {
      this.postMap.clear();
      this.sortedPosts = [];
      return;
    }

    const files = fs.readdirSync(contentDir).filter(f => f.endsWith('.mdx') || f.endsWith('.md'));
    const posts: PostEntity[] = [];

    for (const file of files) {
      const fullPath = path.join(contentDir, file);
      const raw = fs.readFileSync(fullPath, 'utf8');
      const { data, content } = matter(raw);
      const slug = file.replace(/\.mdx?$/, '');

      const entity: PostEntity = {
        slug,
        title: data.title || '',
        description: data.description || '',
        publishedAt: data.publishedAt || '',
        readingTime: data.readingTime,
        tags: Array.isArray(data.tags) ? data.tags : [],
        featured: Boolean(data.featured),
        content,
        contentHash: Buffer.from(raw).toString('base64url').slice(0, 16),
      };

      this.postMap.set(slug, entity);
      posts.push(entity);
    }

    this.sortedPosts = posts.sort(
      (a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime()
    );
    this.isInitialized = true;
  }

  public getBySlug(slug: string): PostEntity | null {
    this.initialize();
    return this.postMap.get(slug) ?? null;
  }

  public getAll(): readonly PostEntity[] {
    this.initialize();
    return this.sortedPosts;
  }
}

export const contentStore = ContentRegistry.getInstance();
```

