Offload BPE token calculation from both the main UI thread and server render cycles into a dedicated, transferable worker thread.

```typescript
// src/workers/tokenizer.worker.ts
import { getEncoding } from 'js-tiktoken';

let encoder: ReturnType<typeof getEncoding> | null = null;

self.onmessage = async (e: MessageEvent<{ text: string; model?: string; reqId: string }>) => {
  const { text, reqId } = e.data;

  try {
    if (!encoder) {
      encoder = getEncoding('cl100k_base');
    }
    const tokens = encoder.encode(text);
    self.postMessage({
      reqId,
      tokenCount: tokens.length,
      sampleTokens: tokens.slice(0, 50),
      success: true,
    });
  } catch (err: unknown) {
    self.postMessage({
      reqId,
      error: err instanceof Error ? err.message : 'Tokenization failed',
      success: false,
    });
  }
};
```

