---

## 4. Concrete Algorithmic Implementation

### 4.1 On-Device Spectral Solver Pipeline

To protect mobile battery and execution budgets, graph clustering executes via a sparse eigensolver pipeline:

1. **Disconnected Components Handling**: Extract the Giant Connected Component (GCC) for full spectral projection; disjoint singletons or tiny sub-graphs ($|V_{\text{sub}}| < 3$) bypass eigendecomposition and are directly evaluated via local isolation metrics.
2. **Sparse Eigensolver**: Execute Lanczos iteration to retrieve the $K$ smallest eigenvalues without dense $N \times N$ materialization.
3. **K-Means Sphere Clustering**: Cluster normalized rows of $U$ using fast Lloyd iteration ($K \in [3, 8]$, max iterations = 25).

### 4.2 iOS Engine (Swift 6 with `Accelerate.framework`)

```swift
import Foundation
import Accelerate

public struct SpectralClusterResult: Sendable {
    public let contactSyncIds: [String]
    public let clusterAssignments: [Int]
    public let isolatedVipIds: [String]
}

public actor SpectralGraphEngine {
    private let maxClusters: Int = 6
    private let vipIsolationThreshold: Float = 0.72

    public init() {}

    public func partitionGraph(
        contactIds: [String],
        strategicScores: [Float],
        adjacencyMatrix: [Float], // Flattened N x N row-major
        dimension: Int
    ) throws -> SpectralClusterResult {
        guard dimension >= 3 else {
            return SpectralClusterResult(
                contactSyncIds: contactIds,
                clusterAssignments: Array(repeating: 0, count: dimension),
                isolatedVipIds: []
            )
        }

        let n = dimension
        // 1. Calculate Degree Vector D
        var degrees = [Float](repeating: 0.0, count: n)
        for i in 0..<n {
            var rowSum: Float = 0.0
            vDSP_sve(adjacencyMatrix + (i * n), 1, &rowSum, vDSP_Length(n))
            degrees[i] = max(rowSum, 1e-6)
        }

        // 2. Form Normalized Symmetric Laplacian: L_sym = I - D^(-1/2) * W * D^(-1/2)
        var invSqrtD = [Float](repeating: 0.0, count: n)
        var count = Int32(n)
        vvrecsqrtf(&invSqrtD, degrees, &count)

        var normalizedLaplacian = [Float](repeating: 0.0, count: n * n)
        for i in 0..<n {
            normalizedLaplacian[i * n + i] = 1.0 // Identity base
            for j in 0..<n {
                let w = adjacencyMatrix[i * n + j]
                if w > 0 {
                    normalizedLaplacian[i * n + j] -= invSqrtD[i] * w * invSqrtD[j]
                }
            }
        }

        // 3. Symmetric Eigen-decomposition via LAPACK (ssyev)
        var jobz: Int8 = 86 // 'V': Compute eigenvalues and eigenvectors
        var uplo: Int8 = 85 // 'U': Upper triangle stored
        var lapackN = Int32(n)
        var lda = Int32(n)
        var eigenvalues = [Float](repeating: 0.0, count: n)
        var work = [Float](repeating: 0.0, count: 3 * n)
        var lwork = Int32(3 * n)
        var info: Int32 = 0

        ssyev_(&jobz, &uplo, &lapackN, &normalizedLaplacian, &lda, &eigenvalues, &work, &lwork, &info)
        guard info == 0 else { throw NSError(domain: "LapackError", code: Int(info)) }

        // 4. Project into K-dimensional Subspace (Skip trivial lambda_0 = 0)
        let k = min(maxClusters, n - 1)
        var spectralEmbedding = [[Float]](repeating: [Float](repeating: 0.0, count: k), count: n)

        for i in 0..<n {
            for j in 0..<k {
                spectralEmbedding[i][j] = normalizedLaplacian[i + (j + 1) * n]
            }
            // Normalize embedding row to unit sphere
            var norm: Float = 0.0
            vDSP_svesq(spectralEmbedding[i], 1, &norm, vDSP_Length(k))
            norm = sqrt(norm)
            if norm > 1e-6 {
                var scale = 1.0 / norm
                vDSP_vsmul(spectralEmbedding[i], 1, &scale, &spectralEmbedding[i], 1, vDSP_Length(k))
            }
        }

        // 5. Lightweight K-Means on Spectral Space
        let assignments = computeKMeans(embeddings: spectralEmbedding, k: k, n: n)

        // 6. Compute VIP Isolation Metric
        var isolatedVips: [String] = []
        for i in 0..<n {
            let score = strategicScores[i]
            if score >= 0.70 { // High-value criteria
                let isolation = computeIsolation(nodeIndex: i, embedding: spectralEmbedding[i], assignments: assignments, embeddings: spectralEmbedding, score: score)
                if isolation >= vipIsolationThreshold {
                    isolatedVips.append(contactIds[i])
                }
            }
        }

        return SpectralClusterResult(
            contactSyncIds: contactIds,
            clusterAssignments: assignments,
            isolatedVipIds: isolatedVips
        )
    }

    private func computeKMeans(embeddings: [[Float]], k: Int, n: Int) -> [Int] {
        var centroids = Array(embeddings.prefix(k))
        var assignments = [Int](repeating: 0, count: n)

        for _ in 0..<20 { // Fixed 20 iterations max
            var changed = false
            for i in 0..<n {
                var minDist = Float.greatestFiniteMagnitude
                var bestCluster = 0
                for c in 0..<k {
                    let d = euclideanDistance(embeddings[i], centroids[c])
                    if d < minDist {
                        minDist = d
                        bestCluster = c
                    }
                }
                if assignments[i] != bestCluster {
                    assignments[i] = bestCluster
                    changed = true
                }
            }
            if !changed { break }
        }
        return assignments
    }

    private func euclideanDistance(_ a: [Float], _ b: [Float]) -> Float {
        var diff = [Float](repeating: 0.0, count: a.count)
        vDSP_vsub(b, 1, a, 1, &diff, 1, vDSP_Length(a.count))
        var sumSq: Float = 0.0
        vDSP_svesq(diff, 1, &sumSq, vDSP_Length(a.count))
        return sqrt(sumSq)
    }

    private func computeIsolation(nodeIndex: Int, embedding: [Float], assignments: [Int], embeddings: [[Float]], score: Float) -> Float {
        let currentCluster = assignments[nodeIndex]
        var intraClusterDist: Float = 0.0
        var count = 0
        for (i, emb) in embeddings.enumerated() where assignments[i] == currentCluster && i != nodeIndex {
            intraClusterDist += euclideanDistance(embedding, emb)
            count += 1
        }
        let meanDist = count > 0 ? (intraClusterDist / Float(count)) : 1.0
        return score * min(meanDist, 1.0)
    }
}
```

---

## 5. Offline Sync, Caching & Incremental Perturbation

```
┌────────────────────────────────────────────────────────┐
│               User Interaction Event                   │
│         (Call, Meeting, WhatsApp, Deal Update)         │
└───────────────────────────┬────────────────────────────┘
                            │
                            ▼
┌────────────────────────────────────────────────────────┐
│            Room / SwiftData Transaction                │
│    • Set contact_graph_edges.is_dirty = TRUE           │
│    • Invalidate Local Delta Cache                      │
└───────────────────────────┬────────────────────────────┘
                            │
              Is Full Recalculation Scheduled?
             ┌──────────────┴──────────────┐
            YES                            NO
             │                             │
             ▼                             ▼
┌───────────────────────────┐ ┌───────────────────────────┐
│ WorkManager / BGTask      │ │ Real-Time UI Query:       │
│ • Periodic (Charging+Idle)│ │ • First-Order Perturb.    │
│ • Full Spectral Solver    │ │ • Use Cached Eigenvectors │
│ • Clean is_dirty flags    │ │ • Zero UI Jitter / Frame  │
└───────────────────────────┘ └───────────────────────────┘
```

### 5.1 Real-Time First-Order Perturbation
When an edge weight shifts by $\Delta W_{uv}$, calculating new eigenvectors from scratch on the main thread is forbidden. We calculate the first-order eigenvalue shift:

$$\Delta \lambda_k \approx \mathbf{v}_k^T (\Delta L_{\text{sym}}) \mathbf{v}_k$$

This reduces runtime complexity from $\mathcal{O}(N^3)$ to $\mathcal{O}(K \cdot \text{deg}(u))$, executing in $<0.5\,\text{ms}$ on mobile CPU threads.

### 5.2 Android WorkManager Periodic Background Worker

```kotlin
package com.netplanner.worker

import android.content.Context
import androidx.work.Constraints
import androidx.work.CoroutineWorker
import androidx.work.PeriodicWorkRequestBuilder
import androidx.work.WorkerParameters
import com.netplanner.data.local.dao.ContactGraphDao
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.util.concurrent.TimeUnit

class NetworkGraphSpectralWorker(
    appContext: Context,
    workerParams: WorkerParameters,
    private val graphDao: ContactGraphDao
) : CoroutineWorker(appContext, workerParams) {

    override suspend fun doWork(): Result = withContext(Dispatchers.Default) {
        try {
            // Check dirty status before running expensive decomposition
            val dirtyEdgeCount = graphDao.getDirtyEdgeCount()
            if (dirtyEdgeCount == 0) return@withContext Result.success()

            val contacts = graphDao.getAllContactsForGraph()
            if (contacts.size < 3) return@withContext Result.success()

            val edges = graphDao.getAllActiveEdges()

            // Build Sparse Adjacency and Solve
            val solver = SpectralSolverAndroid(maxClusters = 6)
            val clusteringOutput = solver.computeClusters(contacts, edges)

            // Persist clusters and VIP isolation metrics atomically
            graphDao.updateSpectralClustersTransaction(
                assignments = clusteringOutput.assignments,
                vipIsolations = clusteringOutput.vipIsolations
            )

            graphDao.clearDirtyFlags()
            Result.success()
        } catch (e: Exception) {
            Result.retry()
        }
    }

    companion object {
        fun buildPeriodicRequest() = PeriodicWorkRequestBuilder<NetworkGraphSpectralWorker>(
            repeatInterval = 24,
            repeatIntervalTimeUnit = TimeUnit.HOURS
        ).setConstraints(
            Constraints.Builder()
                .setRequiresCharging(true)
                .setRequiresDeviceIdle(true)
                .build()
        ).build()
    }
}
```

---

## 6. Edge Cases, Failure Modes & Safety Bounds

| Edge Case | Failure Mode | Mitigation Strategy |
| :--- | :--- | :--- |
| **Fully Disconnected Multi-Graph** | Multiplicity of $\lambda_0 = 0$ is equal to number of components $C > 1$, breaking standard single-component assumption. | Extract Connected Components via Disjoint-Set (Union-Find) in $\mathcal{O}(V + E \cdot \alpha(V))$. Run spectral decomposition only on components with $|V| \ge 4$; mark isolated nodes directly with $C(u) = 0$. |
| **Star Topology / Super-Hub Node** | The user or an executive assistant connects to every single contact, skewing $D^{-1/2}$ and collapsing all embeddings onto a single axis. | Remove the self-root (User ID) from the adjacency graph prior to Laplacian synthesis. Normalize degree vectors using soft-thresholding: $\tilde{D}_{uu} = \min(D_{uu}, 3\sigma_D)$. |
| **Graph Explosion ($N > 5{,}000$)** | Dense matrix allocation causes Out-Of-Memory (OOM) crashes in mobile virtual memory. | Filter graph to active/dormant contacts having $\text{strategicScore} > 0.15$ or interaction within past 365 days; bound active on-device solving graph to top $N=2{,}000$ nodes. |
| **Metric Exploitation (Goodhart's Law)** | An artificial contact added with maximum manual rating without interactions falsely triggers constant high-priority alerts. | Require two independent physical interaction channels (e.g., recorded CallLog + Calendar event or WhatsApp thread) before a contact can exceed $S_u > 0.60$. |

---

## 7. Performance & Battery Safety Verification

1. **Memory Ceiling**: Working memory must not exceed $12\,\text{MB}$ heap allocation during decomposition at $N = 2{,}000$.
2. **CPU Execution Budget**:
   * iOS: `ssyev_` completes in $\le 42\,\text{ms}$ on Apple Silicon A16/A17/M-series for $N=1{,}000$.
   * Android: Native SIMD solver completes in $\le 110\,\text{ms}$ on Snapdragon 8 Gen 2/3 and Tensor G3 for $N=1{,}000$.
3. **Database Concurrency**: Graph edge writes must use batch transactions (`@Transaction` in Room / `ModelContext.transaction` in SwiftData) with `SQLCipher` page cache size pinned to $2\,\text{MB}$ to eliminate disk I/O bottlenecks.

