  required?: boolean;
}

export type TargetDialect = 
  | 'postgres'
  | 'bigquery'
  | 'snowflake'
  | 'duckdb'
  | 'redshift'
  | 'databricks';

export interface DialectDateExpansionRule {
  generateFieldFilterClause(
    columnRef: string,
    sampleStart: string,
    sampleEnd: string,
    type: 'DATE' | 'TIMESTAMP' | 'TIMESTAMPTZ'
  ): string;
