}

export interface AstVerificationIssue {
  code: 
    | 'INVALID_FIELD_FILTER_PLACEMENT'
    | 'SCALAR_FIELD_FILTER_CONFUSION'
    | 'UNKNOWN_COLUMN_ALIAS'
