```

### 4.3 Phase 3 & 4: Virtual SQL Assembly & AST Semantic Verification

The engine synthesizes three verification SQL instances:
1. **$S_{\text{full}}$ (All Tags Active):** Optional brackets `[[...]]` unwrapped, all tags expanded to synthetic clauses.
2. **$S_{\text{pruned}}$ (All Tags Inactive):** Optional brackets `[[...]]` stripped entirely.
3. **$S_{\text{fault\_injection}}$ (Field Filter Misplacement Probe):** Replaces field filters with invalid scalar test markers to verify they are not attached to scalar comparison operators.

```typescript
import { Parser } from 'node-sql-parser'; // or target dialect engine (sqlglot bridge / duckdb-wasm)

export class MetabaseSqlTemplateVerifier {
  private parser: Parser;

  constructor() {
    this.parser = new Parser();
  }

  public verifyTemplate(
    rawSql: string,
    tagDefs: Record<string, MetabaseTagDefinition>,
    tableAliases: Record<string, string>, // e.g., { "orders": "o" }
    columnDataTypes: Record<string, 'DATE' | 'TIMESTAMP' | 'TIMESTAMPTZ'>,
    dialect: TargetDialect
  ): AstVerificationResult {
    const issues: AstVerificationIssue[] = [];
    const expansionRule = DIALECT_EXPANSION_RULES[dialect];
    const extracted = extractTemplateComponents(rawSql);

    // 1. Static Anti-Pattern Checks before AST conversion
    for (const [tagName, tagDef] of Object.entries(tagDefs)) {
      if (tagDef.type === 'dimension') {
        // Pattern: [column] = {{field_filter}} or [column] >= {{field_filter}}
        const badScalarPattern = new RegExp(`([a-zA-Z0-9_\\.\\"]+)\\s*(=|!=|<>|<=|>=|<|>|LIKE|ILIKE|IN)\\s*\\{\\{\\s*${tagName}\\s*\\}\\}`, 'i');
        const badMatch = rawSql.match(badScalarPattern);
        if (badMatch) {
          issues.push({
            code: 'SCALAR_FIELD_FILTER_CONFUSION',
            severity: 'ERROR',
            message: `Field Filter '{{${tagName}}}' is used as a scalar operand for operator '${badMatch[2]}'. Field Filters expand into full boolean expressions (e.g. "col" >= '2026-01-01').`,
            snippet: badMatch[0],
            suggestedFix: `Replace '${badMatch[0]}' with '{{${tagName}}}' directly.`,
          });
        }
      }
    }

    // 2. Synthesize Active-All SQL
    let activeSql = rawSql.replace(/\[\[/g, ' ').replace(/\]\]/g, ' ');
    for (const [tagName, tagDef] of Object.entries(tagDefs)) {
      const tagRegex = new RegExp(`\\{\\{\\s*${tagName}\\s*\\}\\}`, 'g');
      if (tagDef.type === 'dimension') {
        const targetCol = tagDef.name;
        const colType = columnDataTypes[targetCol] || 'TIMESTAMP';
        const alias = tableAliases[targetCol] ? `${tableAliases[targetCol]}.` : '';
        const expandedClause = expansionRule.generateFieldFilterClause(
          `${alias}${targetCol}`,
          '2026-01-01',
          '2026-02-01',
          colType
        );
        activeSql = activeSql.replace(tagRegex, expandedClause);
      } else {
        const colType = columnDataTypes[tagName] || 'DATE';
        const scalarLiteral = expansionRule.generateScalarLiteral('2026-01-01', colType);
        activeSql = activeSql.replace(tagRegex, scalarLiteral);
      }
    }

    // 3. Synthesize Pruned-All SQL
    let prunedSql = rawSql.replace(/\[\[[\s\S]*?\]\]/g, ' ');
    for (const [tagName, tagDef] of Object.entries(tagDefs)) {
      const tagRegex = new RegExp(`\\{\\{\\s*${tagName}\\s*\\}\\}`, 'g');
      if (tagDef.type !== 'dimension') {
        const scalarLiteral = expansionRule.generateScalarLiteral('2026-01-01', 'DATE');
        prunedSql = prunedSql.replace(tagRegex, scalarLiteral);
      }
    }

    // 4. Dialect AST Validation for Both Permutations
    this.validateAstGrammar(activeSql, dialect, 'Active-All State', issues);
    this.validateAstGrammar(prunedSql, dialect, 'Pruned-All State', issues);

    return {
      isValid: issues.filter(i => i.severity === 'ERROR').length === 0,
      dialect,
      tagsDetected: Array.from(extracted.tags.values()),
      issues,
      normalizedSql: activeSql,
    };
  }

  private validateAstGrammar(
    sql: string,
    dialect: TargetDialect,
    stateContext: string,
    issues: AstVerificationIssue[]
  ): void {
    try {
      const dbType = dialect === 'bigquery' ? 'bigquery' : dialect === 'postgres' ? 'postgresql' : 'mysql';
      this.parser.astify(sql, { database: dbType });
    } catch (err: any) {
      issues.push({
        code: 'SYNTAX_ERROR',
        severity: 'ERROR',
        message: `AST Parsing failed in ${stateContext} for dialect '${dialect}': ${err.message}`,
        snippet: sql.slice(Math.max(0, (err.location?.start?.offset || 0) - 40), (err.location?.start?.offset || 0) + 40),
      });
    }
  }
}
```

---

## 5. Offline Schema Sync & AST Verification Cache

To avoid incurring remote warehouse API roundtrips during validation, `metabase-ai-assistant` maintains an offline schema and AST signature cache:

```
                               ┌────────────────────────────────────────────────────────┐
                               │             OFFLINE VERIFICATION CACHE                 │
                               └────────────────────────────────────────────────────────┘
                                                           │
                      ┌────────────────────────────────────┴────────────────────────────────────┐
                      ▼                                                                         ▼
   ┌─────────────────────────────────────┐                                   ┌─────────────────────────────────────┐
   │        dbt Semantic Manifest        │                                   │          AST Signature L2           │
   │  `target/semantic_manifest.json`    │                                   │ `~/.metabase-ai/ast_cache.sqlite`    │
   ├─────────────────────────────────────┤                                   ├─────────────────────────────────────┤
   │ - Table Aliases & Primary Keys      │                                   │ - SHA256(Raw SQL + Tag Metadata)    │
   │ - Column Types (DATE vs TIMESTAMP)  │                                   │ - Dialect Verification Matrix       │
   │ - Partition/Cluster Keys            │                                   │ - TTL: 24 Hours / Invalidate on Git │
   └─────────────────────────────────────┘                                   └─────────────────────────────────────┘
```

### Cache Key Definition:
$$\text{CacheKey} = \text{HMAC-SHA256}\left(\text{RawSQL} \,\|\, \text{TargetDialect} \,\|\, \text{SchemaSignature}\right)$$

When the dbt project is compiled (`dbt compile`), the semantic manifest updates `SchemaSignature`, automatically invalidating stale AST verification states.

---

## 6. Edge Cases, Failure Modes & Safety Bounds

| Edge Case Scenario | Failure Mechanism | Verification Guardrail |
| :--- | :--- | :--- |
| **Nested Optional Blocks**<br>`[[ WHERE 1=1 [[ AND {{date}} ]] ]]` | Inner block omission leaves dangling outer clauses or unbalanced brackets. | Recursive bracket balancer with depth-first AST parsing of all intermediate permutations. |
| **JSON/String Literal Braces**<br>`SELECT '{"date": "2026-01-01"}'::jsonb` | Lexer misidentifies `{}` as Metabase template tags. | Regex scanner skips string literals (`'...'`, `$$...$$`, `"..."`) and SQL comments (`--`, `/* */`). |
| **Partition Key Type Mismatch**<br>BigQuery partitioned on `DATE(created_at)`, filtered by `TIMESTAMP` tag | Silent full-table scan due to partition pruning failure. | AST checks if partition column is wrapped in matching temporal type constructor. |
| **Field Filter on Aggregated Metric**<br>`SELECT dept, COUNT(*) FROM t GROUP BY dept HAVING {{date_tag}}` | Date filter applied after aggregation inside `HAVING` instead of `WHERE`. | Linter flags field filters inside `HAVING` clauses as an anti-pattern unless matching an aggregated date dimension. |

---

## 7. Verification Test Suite Matrix

```typescript
describe('MetabaseSqlTemplateVerifier', () => {
  const verifier = new MetabaseSqlTemplateVerifier();

  const tagDefs: Record<string, MetabaseTagDefinition> = {
    created_date: {
      id: 'created_date',
      name: 'created_at',
      'display-name': 'Created Date',
      type: 'dimension',
    },
    start_date: {
      id: 'start_date',
      name: 'start_date',
      'display-name': 'Start Date',
      type: 'date',
    },
  };

  test('Catches illegal field filter assignment', () => {
    const badSql = `SELECT * FROM orders WHERE orders.created_at = {{created_date}}`;
    const result = verifier.verifyTemplate(badSql, tagDefs, {}, { created_at: 'TIMESTAMP' }, 'postgres');
    expect(result.isValid).toBe(false);
    expect(result.issues[0].code).toBe('SCALAR_FIELD_FILTER_CONFUSION');
  });

  test('Passes valid optional field filter in WHERE clause', () => {
    const validSql = `SELECT * FROM orders WHERE 1=1 [[ AND {{created_date}} ]]`;
    const result = verifier.verifyTemplate(validSql, tagDefs, { created_at: 'o' }, { created_at: 'TIMESTAMP' }, 'postgres');
    expect(result.isValid).toBe(true);
    expect(result.issues.length).toBe(0);
  });

  test('Validates dialect-specific BigQuery timestamp constructors', () => {
    const bqSql = `SELECT * FROM \`project.dataset.orders\` WHERE date_col >= {{start_date}}`;
    const result = verifier.verifyTemplate(bqSql, tagDefs, {}, { date_col: 'DATE' }, 'bigquery');
    expect(result.isValid).toBe(true);
    expect(result.normalizedSql).toContain('DATE("2026-01-01")');
  });
});
```

---

## 8. Rollout Plan & MCP Tool Integration

1. **Phase 1 (Validation Engine Integration):** Embed `MetabaseSqlTemplateVerifier` into `metabase-ai-assistant/src/services/sql-verifier.ts`.
2. **Phase 2 (MCP Tool Exposure):** Expose the MCP tool `verify_metabase_sql_template` to allow autonomous agents and developers to validate queries before writing back to Metabase API or committing to dbt metric definitions.
3. **Phase 3 (Pre-Commit & CI/CD Action):** Add automated validation checks on PRs modifying SQL models with Metabase template tags.

