## 4. Verification Algorithm: 4-Phase Virtual AST Analysis

```
┌───────────────────────────────────────────────────────────────────────────┐
│                      4-PHASE VIRTUAL AST PIPELINE                         │
└───────────────────────────────────────────────────────────────────────────┘
                                      │
   1. LEXICAL PRE-PASS                ▼
      Extract `{{...}}` tags & build optional clause permutation lattice `[[...]]`.
                                      │
   2. GHOST POLYFILL INJECTION        ▼
      Replace tags with typed dialect markers:
      - Field Filter -> `(1=1 AND __mb_col_date__ >= '2026-01-01' AND ...)`
      - Scalar Date  -> `CAST('2026-01-01' AS DATE)`
                                      │
   3. AST PARSING & GRAMMAR CHECK     ▼
      Parse into Dialect AST. Enforce grammar placement rules for Field Filters vs Scalars.
                                      │
   4. SEMANTIC SCOPE RESOLUTION       ▼
      Verify table alias resolution, dbt semantic type mapping, and partition pruning.
```

### 4.1 Phase 1: Lexical Tag & Optional Block Extraction
Extract all `{{tag_name}}` definitions and decompose nested optional blocks `[[ ... ]]`.

```typescript
export interface ExtractedTemplate {
  rawSql: string;
  tags: Map<string, MetabaseTagDefinition>;
  optionalBlocks: Array<{ id: string; content: string; fullMatch: string }>;
}

export function extractTemplateComponents(sql: string): ExtractedTemplate {
  const tags = new Map<string, MetabaseTagDefinition>();
  const optionalBlocks: Array<{ id: string; content: string; fullMatch: string }> = [];

  // Match Metabase tags: {{tag_name}}
  const tagRegex = /\{\{\s*([a-zA-Z0-9_\.\-]+)\s*\}\}/g;
  let match: RegExpExecArray | null;
  while ((match = tagRegex.exec(sql)) !== null) {
    const tagName = match[1];
    if (!tags.has(tagName)) {
      tags.set(tagName, {
        id: tagName,
        name: tagName,
        'display-name': tagName,
        type: 'date', // Default heuristic; refined against schema
      });
    }
  }

  // Match Metabase optional clauses: [[ ... ]]
  const optionalRegex = /\[\[([\s\S]*?)\]\]/g;
  let optIndex = 0;
  while ((match = optionalRegex.exec(sql)) !== null) {
    optionalBlocks.push({
      id: `opt_block_${optIndex++}`,
      content: match[1],
      fullMatch: match[0],
    });
  }

  return { rawSql: sql, tags, optionalBlocks };
}
```

