## 3. Concrete Data Structures

### 3.1 Field & Component Graph Model

```typescript
// src/drift/types.ts

export type FieldDataType =
  | 'STRING'
  | 'NUMBER'
  | 'BOOLEAN'
  | 'DATE'
  | 'DATETIME'
  | 'GEO_JSON'
  | 'CURRENCY'
  | 'PERCENT';

export type FieldOrigin =
  | 'UPSTREAM_RAW'       // Direct table column
  | 'CALCULATED_SOURCE'  // Data source-level calculated field
  | 'CALCULATED_CHART'   // Chart-specific calculated field
  | 'PARAMETER'          // User input parameter
  | 'BLENDED_KEY';       // Joined dimension across sources

export interface SchemaField {
  id: string;
  name: string;
  origin: FieldOrigin;
  dataType: FieldDataType;
  isAggregation: boolean;
  formula?: string;
  sourceId: string;
  rawExpressionTokens?: string[];
  dependencies: string[]; // List of Field IDs directly referenced
}

export interface ChartComponentRef {
  componentId: string;
  componentType: 'TABLE' | 'TIME_SERIES' | 'SCORECARD' | 'BAR' | 'PIE' | 'COMMUNITY_VIZ' | 'FILTER_CONTROL';
  pageId: string;
  pageTitle: string;
  dimensions: string[];
  metrics: string[];
  filterFields: string[];
  sortFields: string[];
}

export interface BlendedDataSource {
  blendId: string;
  blendName: string;
  joinConfigs: {
    leftSourceId: string;
    rightSourceId: string;
    joinType: 'LEFT_OUTER' | 'INNER' | 'FULL_OUTER' | 'CROSS';
    joinKeys: { leftField: string; rightField: string }[];
  }[];
  exposedFields: SchemaField[];
}

export interface ReportDependencyGraph {
  reportId: string;
  reportName: string;
  extractedAt: string;
  schemaVersion: string;
  upstreamSources: Record<string, {
    sourceId: string;
    sourceType: 'BIGQUERY' | 'POSTGRES' | 'SHEETS' | 'DBT';
    tableRef: string;
    columns: Record<string, { name: string; type: string }>;
  }>;
  fields: Record<string, SchemaField>;
  blends: Record<string, BlendedDataSource>;
  components: Record<string, ChartComponentRef>;
  // Forward adjacency list: SourceField -> Set<DependentFieldOrComponent>
  forwardAdjacency: Record<string, string[]>;
}
