```typescript
// auth/DistributedTokenCache.ts
import { ICachePlugin, TokenCacheContext } from '@azure/msal-node';
import Redis from 'ioredis';
import Redlock from 'redlock';

export class RedisTokenCachePlugin implements ICachePlugin {
  constructor(
    private redis: Redis,
    private redlock: Redlock,
    private userId: string
  ) {}

  private get cacheKey(): string {
    return `msal:cache:${this.userId}`;
  }

  async beforeCacheAccess(context: TokenCacheContext): Promise<void> {
    const data = await this.redis.get(this.cacheKey);
    if (data) {
      context.tokenCache.deserialize(data);
    }
  }

  async afterCacheAccess(context: TokenCacheContext): Promise<void> {
    if (context.hasChanged) {
      const lockKey = `locks:msal:${this.userId}`;
      const lock = await this.redlock.acquire([lockKey], 2000);
      try {
        await this.redis.set(this.cacheKey, context.tokenCache.serialize(), 'EX', 60 * 60 * 24 * 30); // 30 days
      } finally {
        await lock.release();
      }
    }
  }
}
```

